def merge_config(defaults, overrides):
    """Return a new config with overrides applied on top of defaults.

    Nested dicts are merged key by key. Neither argument is modified.
    """
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_config(result[key], value)
        else:
            result[key] = value
    return result

def binary_search(items, target):
    """Return the index of target in the sorted list items, or -1 if it is not there."""
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def add_tag(tag, tags=None):
    """Add tag to the list tags (unless it is already there) and return the list.

    If tags is not given, start from a new empty list.
    """
    if tags is None:
        tags = []
    if tag not in tags:
        tags.append(tag)
    return tags

