def drop_empty(record):
    """Return a copy of record without the keys whose value is None, "", [] or {}.

    Other falsy values such as 0 and False are kept. record itself is not changed.
    """
    return {key: value for key, value in record.items() if value not in (None, "", [], {})}

def sort_versions(versions):
    """Return version strings such as '1.10.2' sorted from oldest to newest."""
    return sorted(versions, key=lambda v: [int(part) for part in v.split(".")])

def safe_int(value, default=0):
    """Convert value to int, or return default if it cannot be converted."""
    try:
        return int(value)
    except (TypeError, ValueError):
        return default

def flatten(items):
    """Flatten nested lists and tuples into a single list.

    Anything that is not a list or tuple, including a string, is kept as one item.
    """
    result = []
    for item in items:
        if isinstance(item, (list, tuple)):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def make_multipliers(n):
    """Return a list of n functions; the function at index i multiplies its argument by i."""
    return [lambda x, i=i: x * i for i in range(n)]

def strip_extension(filename, extension):
    """Remove extension (such as '.txt') from the end of filename, if it is there."""
    if extension and filename.endswith(extension):
        return filename[: -len(extension)]
    return filename
